def keep_one_primary_image_per_product(apps, schema_editor):
    ProductImage = apps.get_model('catalog', 'ProductImage')
    database = schema_editor.connection.alias
    product_ids = list(
        ProductImage.objects.using(database)
        .filter(is_primary=True)
        .values_list('product_id', flat=True)
        .distinct()
    )
    for product_id in product_ids:
        primary_images = ProductImage.objects.using(database).filter(
            product_id=product_id,
            is_primary=True,
        ).order_by('sort_order', 'pk')
        keep_id = primary_images.values_list('pk', flat=True).first()
        primary_images.exclude(pk=keep_id).update(is_primary=False)


